// the whistle's tune: eight cycles
let tune = "<[7 ~ 6 4 ~ 4 2 ~] [4 ~ 2 0 ~ 0 2 4] [6 ~ 4 2 ~ 2 0 ~] [2 ~ 4 6 ~ 7 6 4] [7 ~ 7 6 ~ 4 6 7] [4 ~ 6 4 ~ 2 0 ~] [2 4 6 4 2 ~ 0 ~] [0 ~ ~ 2 4 ~ ~ ~]>"
